diff --git a/Makefile b/Makefile
index c923cd0..204c461 100644
--- a/Makefile
+++ b/Makefile
@@ -40,3 +40,23 @@ unit: test/unit/container_test test/unit/sparse_test
 # header deps (the PostgreSQL build we compile against was not configured with --enable-depend)
 $(OBJS): src/rbi.h src/rbi_container.h src/rbi_sparse.h src/rbi_tid.h
 src/rbi_count.o src/rbi_customscan.o src/rbi_am.o: src/rbi_count.h
+
+# Crash-recovery and hot-standby tests (test/recovery/README.md).  These need a
+# whole PostgreSQL *installation* to initdb their own private clusters into,
+# not just a pg_config, and they install the extension into it, so the prefix
+# is named separately rather than derived from PG_CONFIG:
+#
+#   make recovery-check PG_CONFIG=<prefix>/bin/pg_config RECOVERY_PREFIX=<prefix>
+#
+# With RECOVERY_PREFIX unset, run.sh uses the worktree install
+# (../pg_roaring_index-partial/.local/pg) - deliberately NOT the prefix
+# PG_CONFIG points at, so a bare "make recovery-check" cannot install into the
+# dev cluster's tree.  Nothing here touches the dev cluster either way: run.sh
+# creates its own clusters on a private socket directory and port and removes
+# them on exit.
+RECOVERY_PREFIX ?=
+EXTRA_CLEAN += test/recovery/log
+
+.PHONY: recovery-check
+recovery-check:
+	./test/recovery/run.sh $(if $(RECOVERY_PREFIX),--prefix "$(RECOVERY_PREFIX)")
diff --git a/roaring_index--0.1.sql b/roaring_index--0.1.sql
index d2e4e61..499b906 100644
--- a/roaring_index--0.1.sql
+++ b/roaring_index--0.1.sql
@@ -231,7 +231,8 @@ CREATE FUNCTION roaring_index_count_stats(idx regclass, key anyelement,
 										  OUT count bigint,
 										  OUT blocks_skipped bigint,
 										  OUT tids_rechecked bigint,
-										  OUT blocks_rechecked bigint)
+										  OUT blocks_rechecked bigint,
+										  OUT cache_hits bigint)
 RETURNS record
 AS 'MODULE_PATHNAME', 'roaring_index_count_stats'
 LANGUAGE C STRICT VOLATILE PARALLEL UNSAFE;
@@ -239,6 +240,29 @@ LANGUAGE C STRICT VOLATILE PARALLEL UNSAFE;
 COMMENT ON FUNCTION roaring_index_count_stats(regclass, anyelement) IS
 	'roaring_index_count() plus how much of the heap it had to visit';

+/*
+ * Count every key of one index under one snapshot, sharing one per-query
+ * visibility cache across the groups, exactly as the GROUP BY pushdown does
+ * (DESIGN.md section 9).  cache_hits is the number of heap block visits the
+ * cache answered without touching the buffer manager; cache_full counts the
+ * visits that had to be fetched because the cache had used up work_mem.
+ */
+CREATE FUNCTION roaring_index_count_group_stats(idx regclass,
+												use_cache boolean DEFAULT true,
+												OUT groups bigint,
+												OUT count bigint,
+												OUT blocks_skipped bigint,
+												OUT tids_rechecked bigint,
+												OUT blocks_rechecked bigint,
+												OUT cache_hits bigint,
+												OUT cache_full bigint)
+RETURNS record
+AS 'MODULE_PATHNAME', 'roaring_index_count_group_stats'
+LANGUAGE C STRICT VOLATILE PARALLEL UNSAFE;
+
+COMMENT ON FUNCTION roaring_index_count_group_stats(regclass, boolean) IS
+	'count every key of a roaring index, as the GROUP BY pushdown does, and report the heap visits';
+
 /* ------------------------------------------------------------------ */
 -- stats/verify functions (rbi_funcs.c)
 /* ------------------------------------------------------------------ */
@@ -259,7 +283,8 @@ CREATE FUNCTION roaring_index_stats(idx regclass,
 									OUT sparse_segments int8,
 									OUT sparse_members int8,
 									OUT null_tids int8,
-									OUT empty_tids int8)
+									OUT empty_tids int8,
+									OUT slack_bytes int8)
 RETURNS record
 AS 'MODULE_PATHNAME', 'roaring_index_stats'
 LANGUAGE C STRICT VOLATILE PARALLEL RESTRICTED;
diff --git a/src/rbi.h b/src/rbi.h
index 12751e3..9c37b4d 100644
--- a/src/rbi.h
+++ b/src/rbi.h
@@ -544,4 +544,82 @@ extern void rbi_chain_put_items_locked(Relation index, Buffer buf,
 extern void rbi_entry_spill(Relation index, Buffer entrybuf, OffsetNumber entryoff,
 							RBIEntryTuple *entry, const char *payload, Size paylen);

+
+/* ---------- additive helpers (wave 3, write path) ---------- */
+
+/*
+ * GROWTH SLACK INSIDE AN ITEM (DESIGN.md §4).
+ *
+ * An item on a container page may be allocated LARGER than the bytes its
+ * header says it needs.  The spare bytes at its end are slack that the insert
+ * path grows into: adding a member to an ARRAY or RUN container, or a pair to
+ * a sparse segment, then happens by memmove INSIDE the item - under the same
+ * lock, in the same WAL record as the entry tuple, without changing the
+ * item's offset or its ItemIdGetLength() - so no other item on the page
+ * moves and the GenericXLog delta is a handful of bytes instead of a page.
+ *
+ * The two sizes of an item are therefore different things, and both are
+ * needed:
+ *
+ *	 rbi_item_size(item)		its LOGICAL size, derived from the header;
+ *								what every reader uses, and what the item
+ *								would be written back as.
+ *	 ItemIdGetLength(iid)		its ALLOCATED length on the page, which is
+ *								what the item may grow to in place.
+ *
+ * Readers never look at the allocated length (they walk items by their
+ * headers), so slack is invisible to them; code that copies an item out of a
+ * page by ItemIdGetLength() - VACUUM does - still works because the allocated
+ * length is capped at RBI_CONTAINER_MAX_SIZE, the size of every item work
+ * buffer.  Slack bytes are always zeroed when an item is written, so that
+ * the page image stays deterministic and the WAL delta stays small.
+ *
+ * A bulk-built index gets no slack at all: it is read-mostly, and the space
+ * would be pure loss.  Slack appears when an insert first grows an item.
+ */
+#define RBI_ITEM_SLACK_MIN		8	/* smallest slack worth having */
+#define RBI_ITEM_SLACK_MAX		64	/* and the most, per item */
+#define RBI_ITEM_SLACK_FRACTION 8	/* size/8, clamped into the above */
+
+/* The most bytes of slack an item may hold (alignment padding included). */
+#define RBI_ITEM_SLACK_LIMIT	(RBI_ITEM_SLACK_MAX + MAXIMUM_ALIGNOF - 1)
+
+/*
+ * Allocated length to write an item of logical size `size` with, so that it
+ * has room to grow in place.  Always >= size, always MAXALIGNed and never
+ * above RBI_CONTAINER_MAX_SIZE; a BITSET container, which is already the
+ * largest an item can be, gets its exact size.  The caller checks that the
+ * result fits on the page and falls back to `size` if it does not.
+ */
+extern Size rbi_item_alloc_size(const RBIContainer *item, Size size);
+
+/* Free bytes inside an item of allocated length itemlen. */
+static inline Size
+rbi_item_slack(const RBIContainer *item, Size itemlen)
+{
+	Size		size = rbi_item_size(item);
+
+	return (itemlen > size) ? itemlen - size : 0;
+}
+
+/*
+ * rbi_chain_put_items_locked() and rbi_chain_put_container_locked() with
+ * control over slack: with slack = true the items are written with room to
+ * grow (and the items[] buffers must have RBI_CONTAINER_MAX_SIZE bytes of
+ * capacity, because their slack is zeroed in place before the copy).  The
+ * two original functions are these with slack = false, which is what VACUUM
+ * and the build want: they write items at their exact size.
+ */
+extern void rbi_chain_put_items_locked_ext(Relation index, Buffer buf,
+										   Buffer entrybuf, OffsetNumber entryoff,
+										   RBIEntryTuple *entry,
+										   OffsetNumber off, bool replace,
+										   RBIContainer **items, int nitems,
+										   bool slack);
+
+extern void rbi_chain_put_container_locked_ext(Relation index, Buffer buf,
+											   Buffer entrybuf, OffsetNumber entryoff,
+											   RBIEntryTuple *entry, RBIContainer *c,
+											   int *ncontainers_delta, bool slack);
+
 #endif							/* RBI_H */
diff --git a/src/rbi_am.c b/src/rbi_am.c
index 95da5e8..50523d1 100644
--- a/src/rbi_am.c
+++ b/src/rbi_am.c
@@ -20,8 +20,10 @@
 #include "catalog/pg_type.h"
 #include "commands/vacuum.h"
 #include "miscadmin.h"
+#include "nodes/pathnodes.h"
 #include "storage/bufmgr.h"
 #include "storage/indexfsm.h"
+#include "utils/array.h"
 #include "utils/builtins.h"
 #include "utils/guc.h"
 #include "utils/lsyscache.h"
@@ -190,8 +192,248 @@ rbioptions(Datum reloptions, bool validate)
 }

 /*
- * Cost estimate: exactly the generic estimate, but a roaring index has no
- * correlation with the heap order (contrib/bloom does the same).
+ * Peel binary-coercion relabels off an expression, so that a varchar column
+ * compared with a text constant presents the constant the opclass will see.
+ */
+static Node *
+rbi_cost_strip(Node *node)
+{
+	while (node != NULL && IsA(node, RelabelType))
+		node = (Node *) ((RelabelType *) node)->arg;
+	return node;
+}
+
+/*
+ * Does this index's opclass extract many keys from one value (DESIGN.md §17)?
+ * The presence of support function 2 is the same test rbi_fill_state() makes.
+ */
+static bool
+rbi_index_is_multikey(IndexOptInfo *index)
+{
+	return OidIsValid(get_opfamily_proc(index->opfamily[0],
+										index->opcintype[0],
+										index->opcintype[0],
+										RBI_EXTRACTVALUE_PROC));
+}
+
+/*
+ * Extract one multi-key query at plan time and say whether answering it means
+ * emitting every posting of every entry (DESIGN.md §17's RBI_QMODE_ALL).
+ *
+ * rbi_extract_query() wants an RBIState, but only for the extractQuery
+ * FmgrInfo and the collation; nothing here touches an index.  A missing
+ * extraction function means the question cannot be answered, which is costed
+ * as the expensive answer.
+ */
+static bool
+rbi_query_is_full_scan(IndexOptInfo *index, StrategyNumber strategy,
+					   Datum query)
+{
+	Oid			proc;
+	FmgrInfo	flinfo;
+	RBIState	state;
+	RBIQuery	q;
+	MemoryContext cxt;
+	MemoryContext oldcxt;
+	bool		full;
+
+	proc = get_opfamily_proc(index->opfamily[0], index->opcintype[0],
+							 index->opcintype[0], RBI_EXTRACTQUERY_PROC);
+	if (!OidIsValid(proc))
+		return true;
+
+	cxt = AllocSetContextCreate(CurrentMemoryContext,
+								"roaring cost query extract",
+								ALLOCSET_SMALL_SIZES);
+	oldcxt = MemoryContextSwitchTo(cxt);
+
+	memset(&state, 0, sizeof(state));
+	state.multikey = true;
+	state.collation = index->indexcollations[0];
+	fmgr_info(proc, &flinfo);
+	state.extractquery = flinfo;
+
+	rbi_extract_query(&state, query, strategy, &q);
+	full = (q.mode == RBI_QMODE_ALL);
+
+	MemoryContextSwitchTo(oldcxt);
+	MemoryContextDelete(cxt);
+
+	return full;
+}
+
+/*
+ * `col op ANY (array)`: each element is a query of its own and their answers
+ * go into the same bitmap, so one element that needs the whole index makes
+ * the scan a full one.  An array that is not available at plan time has to be
+ * assumed to contain such an element.
+ */
+static bool
+rbi_array_query_is_full_scan(IndexOptInfo *index, StrategyNumber strategy,
+							 Node *arraynode)
+{
+	Const	   *con = (Const *) arraynode;
+	ArrayType  *arr;
+	Oid			elemtype;
+	int16		elmlen;
+	bool		elmbyval;
+	char		elmalign;
+	Datum	   *elems;
+	bool	   *nulls;
+	int			nelems;
+	int			i;
+	bool		full = false;
+
+	if (arraynode == NULL || !IsA(arraynode, Const))
+		return true;
+	if (con->constisnull)
+		return false;			/* `col op ANY (NULL)` is never true */
+
+	arr = DatumGetArrayTypeP(con->constvalue);
+	elemtype = ARR_ELEMTYPE(arr);
+	get_typlenbyvalalign(elemtype, &elmlen, &elmbyval, &elmalign);
+	deconstruct_array(arr, elemtype, elmlen, elmbyval, elmalign,
+					  &elems, &nulls, &nelems);
+
+	for (i = 0; i < nelems && !full; i++)
+	{
+		if (nulls[i])
+			continue;			/* never true, nothing is scanned for it */
+		full = rbi_query_is_full_scan(index, strategy, elems[i]);
+	}
+
+	pfree(elems);
+	pfree(nulls);
+	if ((Pointer) arr != DatumGetPointer(con->constvalue))
+		pfree(arr);
+
+	return full;
+}
+
+/*
+ * Will rbigetbitmap() have to walk the WHOLE index for this path, emitting
+ * every posting of every entry and leaving every candidate row to be
+ * rechecked in the heap?
+ *
+ * rbigetbitmap() answers ONE qual per scan and marks the rest for recheck,
+ * choosing the most selective-looking one: a plain operator first, then a
+ * ScalarArrayOp, then a null test.  The cost of the scan is the cost of the
+ * qual it answers, so the choice is mirrored here.
+ *
+ * A full walk is what the AM does for:
+ *
+ *	- `col IS NOT NULL`, which is every entry but the reserved NULL one
+ *	  (DESIGN.md §14);
+ *	- a multi-key query the extractor answers with RBI_QMODE_ALL: a phrase, a
+ *	  prefix, a NOT, a weight mask, `<@`, `@> '{}'`, a NULL element, or more
+ *	  than RBI_MAX_QUERY_KEYS keys (DESIGN.md §17).  Correctness is preserved
+ *	  by the recheck, but the scan reads the whole index and hands the heap
+ *	  every indexed row;
+ *	- and a multi-key query whose value is not a plan-time Const (a Param):
+ *	  the MODE follows the query's shape, not just its value, so an unknown
+ *	  value has to be priced as the expensive shape.
+ *
+ * Handing genericcostestimate() an empty GenericCosts instead priced these
+ * as selective lookups - a prefix query estimated at 192 cost units against
+ * the sequential scan's 9156, for a scan that emitted 1.18M posting TIDs and
+ * rechecked 198k rows and ran 2.6x slower than that sequential scan (the
+ * 2026-09-21 follow-up review).
+ */
+static bool
+rbi_scan_walks_whole_index(IndexPath *path)
+{
+	IndexOptInfo *index = path->indexinfo;
+	Node	   *chosen = NULL;
+	int			bestrank = 3;
+	ListCell   *lc;
+
+	if (index->nkeycolumns != 1)
+		return false;
+
+	foreach(lc, path->indexclauses)
+	{
+		IndexClause *iclause = (IndexClause *) lfirst(lc);
+		ListCell   *lc2;
+
+		if (iclause->indexcol != 0)
+			continue;
+
+		foreach(lc2, iclause->indexquals)
+		{
+			RestrictInfo *rinfo = lfirst_node(RestrictInfo, lc2);
+			Node	   *clause = (Node *) rinfo->clause;
+			int			rank;
+
+			if (IsA(clause, NullTest))
+				rank = 2;
+			else if (IsA(clause, ScalarArrayOpExpr))
+				rank = 1;
+			else if (IsA(clause, OpExpr))
+				rank = 0;
+			else
+				continue;
+
+			if (rank < bestrank)
+			{
+				bestrank = rank;
+				chosen = clause;
+			}
+		}
+	}
+
+	if (chosen == NULL)
+		return false;
+
+	if (IsA(chosen, NullTest))
+		return ((NullTest *) chosen)->nulltesttype == IS_NOT_NULL;
+
+	/* A scalar opclass looks ONE key up, whatever the operator's operand. */
+	if (!rbi_index_is_multikey(index))
+		return false;
+
+	if (IsA(chosen, OpExpr))
+	{
+		OpExpr	   *op = (OpExpr *) chosen;
+		StrategyNumber strategy;
+		Node	   *arg;
+
+		if (list_length(op->args) != 2)
+			return true;
+		strategy = (StrategyNumber) get_op_opfamily_strategy(op->opno,
+															index->opfamily[0]);
+		if (strategy == 0)
+			return true;
+		arg = rbi_cost_strip((Node *) lsecond(op->args));
+		if (arg == NULL || !IsA(arg, Const))
+			return true;
+		if (((Const *) arg)->constisnull)
+			return false;		/* a strict operator: never true */
+		return rbi_query_is_full_scan(index, strategy,
+									  ((Const *) arg)->constvalue);
+	}
+
+	{
+		ScalarArrayOpExpr *saop = (ScalarArrayOpExpr *) chosen;
+		StrategyNumber strategy;
+
+		if (list_length(saop->args) != 2)
+			return true;
+		strategy = (StrategyNumber) get_op_opfamily_strategy(saop->opno,
+															index->opfamily[0]);
+		if (strategy == 0)
+			return true;
+		if (strategy == RBI_STRAT_EQUAL)
+			return false;		/* a union of single-key lookups */
+		return rbi_array_query_is_full_scan(index, strategy,
+											rbi_cost_strip((Node *) lsecond(saop->args)));
+	}
+}
+
+/*
+ * Cost estimate: the generic estimate, with two corrections.  A roaring index
+ * has no correlation with the heap order (contrib/bloom does the same), and a
+ * scan that has to walk the whole index is priced as one rather than as the
+ * selective lookup its predicate's output selectivity suggests.
  */
 void
 rbicostestimate(PlannerInfo *root, IndexPath *path, double loop_count,
@@ -200,9 +442,43 @@ rbicostestimate(PlannerInfo *root, IndexPath *path, double loop_count,
 				double *indexPages)
 {
 	GenericCosts costs = {0};
+	bool		fullscan = rbi_scan_walks_whole_index(path);
+
+	/*
+	 * A full walk visits every index tuple - every (key, row) posting, which
+	 * is what pg_class.reltuples of a roaring index counts - and
+	 * genericcostestimate() then prorates that into every index page.
+	 */
+	if (fullscan)
+		costs.numIndexTuples = Max(path->indexinfo->tuples, 1.0);

 	genericcostestimate(root, path, loop_count, &costs);

+	if (fullscan)
+	{
+		double		allpages = Max((double) path->indexinfo->pages, 1.0);
+
+		/*
+		 * reltuples of an index is whatever the last ANALYZE or VACUUM left
+		 * there, and ANALYZE writes the HEAP's row count onto every index of
+		 * a table, so the prorated page count can come out short of the
+		 * index the scan really reads.  Charge the rest of it.
+		 */
+		if (costs.numIndexPages < allpages)
+		{
+			costs.indexTotalCost += (allpages - costs.numIndexPages) *
+				costs.spc_random_page_cost;
+			costs.numIndexPages = allpages;
+		}
+
+		/*
+		 * And nothing is filtered out before the heap: every candidate the
+		 * scan emits is fetched and rechecked there, so the heap side is the
+		 * cost of a full recheck and not of the predicate's own selectivity.
+		 */
+		costs.indexSelectivity = 1.0;
+	}
+
 	*indexStartupCost = costs.indexStartupCost;
 	*indexTotalCost = costs.indexTotalCost;
 	*indexSelectivity = costs.indexSelectivity;
diff --git a/src/rbi_build.c b/src/rbi_build.c
index f810643..e7861d2 100644
--- a/src/rbi_build.c
+++ b/src/rbi_build.c
@@ -14,6 +14,28 @@
  * the build changes, because the sort orders the codes of each key
  * ascending either way.
  *
+ * Every page is written through the bulk-write API (storage/bulk_write.h),
+ * which is what nbtree and GiST builds use: pages are prepared in
+ * backend-local memory, written straight to the file without going through
+ * shared buffers, WAL-logged in batches of up to 32 as full-page images (or
+ * not at all, for an unlogged relation or wal_level = minimal, in which case
+ * the relation is registered for the next sync instead), and each page is
+ * written exactly ONCE.  That last property is what makes it fast: the old
+ * route through the buffer manager logged a GenericXLog record per entry
+ * tuple, so a million-key index paid a million page diffs and a million WAL
+ * records to fill 15,000 pages.
+ *
+ * Writing each page once means every page has to be final before it is
+ * written, and a bucket page is only final when the last entry that hashes to
+ * it has been added.  Bucket pages therefore live in memory - one 8 KB image
+ * per bucket page that actually holds entries - until pass 2 is over
+ * (rbi_build_flush_buckets()).  That is the one cost of this route: the
+ * bucket directory is sized at about three quarters of a page per bucket, so
+ * the images are roughly 1.3 times the bytes the entry tuples need, bounded
+ * by RBI_MAX_BUCKETS pages (512 MB) in the worst case and by nothing else.
+ * Container pages are final as soon as the next container does not fit, so
+ * only one of those exists per open key at a time.
+ *
  *-------------------------------------------------------------------------
  */
 #include "postgres.h"
@@ -28,6 +50,7 @@
 #include "miscadmin.h"
 #include "nodes/execnodes.h"
 #include "storage/bufmgr.h"
+#include "storage/bulk_write.h"
 #include "utils/datum.h"
 #include "utils/lsyscache.h"
 #include "utils/memutils.h"
@@ -98,14 +121,27 @@ typedef struct RBIBuilder

 	bool		spilled;		/* posting set lives on container pages */
 	BlockNumber head;
-	BlockNumber curblk;			/* block reserved for pageimg */
-	PGAlignedBlock *pageimg;	/* container page under construction */
+	BlockNumber curblk;			/* block pagebuf will be written to */
+	BulkWriteBuffer pagebuf;	/* container page under construction */
 	bool		haspage;

 	uint32		nitems;			/* containers and segments (entry.ncontainers) */
 	uint64		ntids;
 } RBIBuilder;

+/*
+ * One bucket page under construction.  The image is a bulk-write buffer, so
+ * that writing it out at the end of the build hands the very same memory to
+ * the bulk writer instead of copying it.
+ */
+typedef struct RBIBuildPage
+{
+	struct RBIBuildPage *next;	/* next page of this bucket's chain */
+	struct RBIBuildPage *next2; /* next overflow page in block order */
+	BlockNumber blkno;
+	BulkWriteBuffer buf;		/* the image, NULL once it has been written */
+} RBIBuildPage;
+
 typedef struct RBIBuildState
 {
 	Relation	index;
@@ -124,6 +160,18 @@ typedef struct RBIBuildState
 	MemoryContext buildctx;		/* lives for the whole build */
 	MemoryContext tmpctx;		/* reset per heap tuple / per key group */

+	/*
+	 * Page writing (see the file header): one bulk writer for the whole
+	 * build, blocks handed out by a counter instead of by extending the
+	 * relation, and the bucket pages kept in memory until pass 2 is over.
+	 */
+	BulkWriteState *bulk;
+	BlockNumber nblocks;		/* blocks handed out so far */
+	struct RBIBuildPage **bucketpages;	/* head page of each bucket, or NULL */
+	struct RBIBuildPage *overflow;		/* bucket pages beyond the heads, in */
+	struct RBIBuildPage *overflowlast;	/* block order */
+	int64		nbucketpages;
+
 	RBIBuilder **builders;		/* open builders of the current hash */
 	int			nbuilders;
 	int			maxbuilders;
@@ -137,72 +185,165 @@ static void rbi_builder_flush(RBIBuildState *bs, RBIBuilder *b);
 static void rbi_builder_close_segment(RBIBuildState *bs, RBIBuilder *b);

 /* ---------------------------------------------------------------------
- * Raw page helpers
+ * Page writing
  *
  * During a build nobody else can see the index, so pages are prepared in
- * backend-local memory and written out in one full-page WAL record.  A block
- * is reserved (the relation is extended) before its contents are final so
- * that the previous page of a chain can store the right rightlink.
+ * backend-local memory and handed to the bulk writer, which writes each of
+ * them exactly once and WAL-logs them in batches.  Block numbers come from a
+ * counter: the meta page is block 0, the bucket directory takes blocks
+ * 1 .. nbuckets, and container pages and further bucket pages are handed the
+ * next free block as they are needed - the same order the buffer-manager
+ * route extended the relation in, so an index built by either route has the
+ * same page at the same block.
  * --------------------------------------------------------------------- */

